from pathlib import Path
from evidence_paths import EVIDENCE_ROOT, FINAL_DIR, APPROVALS, load_source_json
import base64, json, mimetypes, hashlib, html

ROOT=EVIDENCE_ROOT
WORK=Path(__file__).resolve().parent
OUT=FINAL_DIR/'열교환기 한눈에.html'
doc=next(d for d in load_source_json(APPROVALS)['documents'] if d['docId']=='334757')
files=[]
for i,p in enumerate([Path(doc['bodyPdfPath'])]+sorted(Path(doc['attachmentDir']).iterdir())):
    if not p.is_file(): continue
    raw=p.read_bytes();files.append({'id':str(i),'name':p.name,'size':len(raw),'mime':mimetypes.guess_type(p.name)[0] or 'application/octet-stream','sha256':hashlib.sha256(raw).hexdigest(),'base64':base64.b64encode(raw).decode()})
assert len(files)==7

def uri(p):
    return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()

default=WORK/'visual_sources/installation-route.png'
if not default.exists(): default=WORK/'visual_sources/install-slide-2.png'
drawings=[
    {'id':'install','label':'설치 개요','title':'5층 열교환기 → 4층 송풍기','caption':'열교환기 설치도.pptx · 슬라이드 2 · 원문에 표시된 설치·공급 계획','src':uri(default)},
    {'id':'front','label':'정면도','title':'열회수장치 설치 정면도','caption':'열회수장치 설치 정면도.pdf · 1쪽 · 계획도면','src':uri(WORK/'visual_sources/elevation-full.png')},
    {'id':'plan','label':'평면도','title':'열회수장치 설치 평면도','caption':'열회수장치설치 평면도.pdf · 1쪽 · 계획도면','src':uri(WORK/'visual_sources/plan-full.png')},
    {'id':'pid','label':'기존 배관도','title':'기존 건조기 P&ID','caption':'열교환기 설치도.pptx · 슬라이드 2 삽입 P&ID · 기존 설비 참고','src':uri(WORK/'image3.png')},
]
tabs=''.join(f'<button type="button" role="tab" aria-selected="{str(i==0).lower()}" data-drawing="{d["id"]}">{d["label"]}</button>' for i,d in enumerate(drawings))
file_buttons=''.join(f'<button type="button" class="file" data-file="{f["id"]}"><span>{Path(f["name"]).suffix[1:].upper()}</span><b>{html.escape(f["name"])}</b><i>↓</i></button>' for f in files)
